<?php
declare(strict_types=1);require __DIR__.'/app/bootstrap.php';$me=require_login();if(!setting_bool('marketplace_v550_pos_enabled',true)){http_response_code(404);exit('Seller POS is disabled.');}$shops=mp550_user_shops((int)$me['id'],true);if(!$shops){http_response_code(403);exit('No POS shop is assigned to your account.');}$shopId=(int)($_GET['shop']??$shops[0]['id']);if(!in_array($shopId,array_map(fn($s)=>(int)$s['id'],$shops),true))$shopId=(int)$shops[0]['id'];$shop=mp550_shop($shopId);$assignment=mp550_pos_assignment_for((int)$me['id'],$shopId);if(!$assignment){try{db()->prepare("INSERT INTO marketplace_pos_assignments_v550(shop_id,user_id,assigned_by,terminal_name,permissions_json,status,created_at,updated_at) VALUES(?,?,?,?,?,1,NOW(),NOW()) ON DUPLICATE KEY UPDATE status=1,updated_at=NOW()")->execute([$shopId,(int)$me['id'],(int)$me['id'],'Owner Counter',mp550_json(['sales'=>1,'discounts'=>1,'returns'=>0])]);$assignment=mp550_pos_assignment_for((int)$me['id'],$shopId);}catch(Throwable $e){}}$shiftId=$assignment?mp550_open_shift($assignment,(int)$me['id'],0):0;$key='mp550_pos_cart_'.$shopId;if(!isset($_SESSION[$key])||!is_array($_SESSION[$key]))$_SESSION[$key]=[];$flash='';$err='';if(($_SERVER['REQUEST_METHOD']??'')==='POST'){csrf_check();try{$action=(string)($_POST['action']??'');if($action==='add'){$pid=(int)($_POST['product_id']??0);$p=mp550_product($pid);if(!$p||(int)$p['shop_id']!==$shopId)throw new RuntimeException('Product is not part of this POS shop.');$qty=max(1,(int)($_POST['qty']??1));$_SESSION[$key][$pid]=min((int)$p['stock'],(int)($_SESSION[$key][$pid]??0)+$qty);$flash='Item added.';}elseif($action==='remove'){unset($_SESSION[$key][(int)$_POST['product_id']]);}elseif($action==='checkout'){if(!$_SESSION[$key])throw new RuntimeException('POS cart is empty.');$old=$_SESSION['mp550_cart']??null;$_SESSION['mp550_cart']=$_SESSION[$key];$r=mp550_checkout(0,['name'=>trim((string)($_POST['customer_name']??'Walk-in Customer'))?:'Walk-in Customer','phone'=>trim((string)($_POST['customer_phone']??'')),'email'=>'','address'=>'POS Counter','note'=>'POS sale by '.$me['name']],(string)($_POST['payment_method']??'cash'),'pos');if($old===null)unset($_SESSION['mp550_cart']);else $_SESSION['mp550_cart']=$old;$_SESSION[$key]=[];if($shiftId){$sum=0;foreach($r['orders'] as $oid){$o=mp550_order((int)$oid);$sum+=(float)($o['grand_total']??0);}db()->prepare('UPDATE marketplace_pos_shifts_v550 SET sales_total=sales_total+?,order_count=order_count+?,updated_at=NOW() WHERE id=?')->execute([$sum,count($r['orders']),$shiftId]);}$flash='Sale completed. Order(s): '.implode(', ',array_map('intval',$r['orders']));}elseif($action==='close_shift'){if($shiftId){db()->prepare("UPDATE marketplace_pos_shifts_v550 SET status='closed',closed_at=NOW(),closing_cash=? WHERE id=?")->execute([(float)($_POST['closing_cash']??0),$shiftId]);$flash='Shift closed.';header('Location: /seller-pos.php?shop='.$shopId);exit;}}}catch(Throwable $e){$err=$e->getMessage();}}$products=mp550_products(['shop'=>$shopId,'q'=>trim((string)($_GET['q']??''))],80);$posItems=[];$total=0;foreach($_SESSION[$key] as $pid=>$qty){$p=mp550_product((int)$pid);if(!$p)continue;$d=mp550_best_discount($p,(int)$qty,null);$line=((float)$p['price']*(int)$qty)-(float)$d['amount'];$posItems[]=['p'=>$p,'qty'=>(int)$qty,'line'=>$line];$total+=$line;}mp550_public_header('Seller POS');
?>
<section class="pos-shell"><header class="pos-top"><div><span>SELLER POS</span><h1><?=e($shop['name'])?></h1><p>Terminal: <?=e($assignment['terminal_name']??'POS')?> · Cashier <?=e($me['name'])?></p></div><div><a href="/seller-marketplace.php?shop=<?=$shopId?>">Seller Center</a><select onchange="location='?shop='+this.value"><?php foreach($shops as $s):?><option value="<?=(int)$s['id']?>" <?=$shopId===(int)$s['id']?'selected':''?>><?=e($s['name'])?></option><?php endforeach;?></select></div></header><?php if($flash):?><div class="mp550-alert ok"><?=e($flash)?></div><?php endif;?><?php if($err):?><div class="mp550-alert err"><?=e($err)?></div><?php endif;?><div class="pos-layout"><section class="pos-products"><form class="pos-search"><input name="q" value="<?=e((string)($_GET['q']??''))?>" autofocus placeholder="Search product / SKU / barcode"><button>Search</button></form><div class="pos-grid"><?php foreach($products as $p):?><form method="post" class="pos-product"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="add"><input type="hidden" name="product_id" value="<?=(int)$p['id']?>"><div class="pic"<?=!empty($p['image_url'])?' style="background-image:url(\''.e($p['image_url']).'\')"':''?>></div><div><small><?=e($p['sku']?:$p['category_name'])?></small><b><?=e($p['title'])?></b><strong><?=mp550_money((float)$p['sale_price'])?></strong><span><?=(int)$p['stock']?> in stock</span></div><button>Add</button></form><?php endforeach;?></div></section><aside class="pos-cart"><div class="pos-cart-head"><div><span>CURRENT SALE</span><h2><?=count($posItems)?> lines</h2></div><b><?=mp550_money($total)?></b></div><div class="pos-lines"><?php foreach($posItems as $it):?><div><span><b><?=e($it['p']['title'])?></b><small><?=e((string)$it['qty'])?> × <?=mp550_money((float)$it['p']['price'])?></small></span><strong><?=mp550_money((float)$it['line'])?></strong><form method="post"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="remove"><input type="hidden" name="product_id" value="<?=(int)$it['p']['id']?>"><button>×</button></form></div><?php endforeach;?><?php if(!$posItems):?><p class="empty">Scan/search a product to begin a sale.</p><?php endif;?></div><form method="post" class="pos-checkout"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="checkout"><label>Customer name<input name="customer_name" value="Walk-in Customer"></label><label>Phone<input name="customer_phone"></label><div class="payment-options compact"><label><input type="radio" name="payment_method" value="cash" checked><span><b>Cash</b></span></label><label><input type="radio" name="payment_method" value="card"><span><b>Card</b></span></label><label><input type="radio" name="payment_method" value="bank_transfer"><span><b>Transfer</b></span></label></div><button class="mp550-btn wide" <?=$posItems?'':'disabled'?>>Complete sale · <?=mp550_money($total)?></button></form><form method="post" class="close-shift"><input type="hidden" name="_csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="close_shift"><input type="number" name="closing_cash" min="0" placeholder="Closing cash"><button>Close shift</button></form></aside></div></section>
<?php mp550_public_footer(); ?>
